'use strict';
const KEY='studyBloomDataV1';
const blank={subjects:[],assignments:[],events:[],semesters:[],grades:[],professors:[],holidays:[],important:[],activities:[],readings:[],goals:[],notes:[],decks:[],studySessions:[],water:0,waterGoal:8,theme:'auto',settings:{name:'',weekStart:1},activeSemester:'',notificationSettings:{enabled:false,quietStart:'22:00',quietEnd:'07:00'},notifiedReminders:[],revisionTopics:[]};
let data=load(), current='today', deadlineMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1), deadlineCourse='all', timer={left:1500,total:1500,running:false,id:null};
const $=s=>document.querySelector(s), view=$('#view'), root=$('#modalRoot');
function load(){try{return {...structuredClone(blank),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return structuredClone(blank)}}
function save(){localStorage.setItem(KEY,JSON.stringify(data));render()}
const id=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+Math.random().toString(16).slice(2);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>d?new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric',year:'numeric'}).format(new Date(d+'T12:00:00')):'';
const dt=d=>d?new Date(d):new Date(8640000000000000);
const subject=x=>data.subjects.find(s=>s.id===x)||{name:'',code:'',colour:'#e63d83'};
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function applyTheme(){const dark=data.theme==='dark'||(data.theme==='auto'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.classList.toggle('dark',dark);document.querySelector('meta[name=theme-color]').content=dark?'#171312':'#f8f1e7'}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(data.theme==='auto')applyTheme()});
function title(t){$('#pageTitle').textContent=t;$('#todayLabel').textContent=new Intl.DateTimeFormat('en-CA',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}
function empty(name){return `<div class="empty"><strong>No ${name} yet</strong><span>Use the single add button above.</span></div>`}
function dueText(d){if(!d)return '';const n=Math.ceil((new Date(d)-new Date().setHours(0,0,0,0))/86400000);return n<0?`${Math.abs(n)}d overdue`:n===0?'Due today':n===1?'Due tomorrow':`Due in ${n}d`}
function render(){applyTheme();function notificationStatusText(){if(!('Notification'in window))return'Notifications are not supported by this browser.';return Notification.permission==='granted'?'Enabled on this device':Notification.permission==='denied'?'Blocked in browser settings':'Permission has not been requested'}
async function enableNotifications(){if(!('Notification'in window)){toast('Notifications are unavailable');return}const permission=await Notification.requestPermission();data.notificationSettings={...(data.notificationSettings||{}),enabled:permission==='granted'};localStorage.setItem(KEY,JSON.stringify(data));const status=$('#notificationStatus');if(status)status.textContent=notificationStatusText();toast(permission==='granted'?'Notifications enabled':'Notifications were not enabled')}
function inQuietHours(){const now=new Date(),cur=now.toTimeString().slice(0,5),a=data.notificationSettings?.quietStart||'22:00',b=data.notificationSettings?.quietEnd||'07:00';return a>b?(cur>=a||cur<b):(cur>=a&&cur<b)}
async function sendPlannerNotification(title,body,tag){if(!('Notification'in window)||Notification.permission!=='granted')return false;try{const reg=await navigator.serviceWorker.ready;await reg.showNotification(title,{body,icon:'./icon.svg',badge:'./icon.svg',tag,data:{url:'./'},renotify:false});return true}catch{return false}}
async function checkReminders(){if(!data.notificationSettings?.enabled||Notification.permission!=='granted'||inQuietHours())return;const now=Date.now();data.notifiedReminders=data.notifiedReminders||[];for(const a of data.assignments){if(a.done||!a.due||!a.reminderMinutes)continue;const due=new Date(a.due).getTime(),fire=due-Number(a.reminderMinutes)*60000,key=`assignment-${a.id}-${a.reminderMinutes}`;if(now>=fire&&now<due+3600000&&!data.notifiedReminders.includes(key)){const course=subject(a.subjectId);if(await sendPlannerNotification(a.title,`${course.code||course.name||'Deadline'} · ${dueText(a.due)}`,key)){data.notifiedReminders.push(key);localStorage.setItem(KEY,JSON.stringify(data))}}}}
setInterval(checkReminders,30000);window.addEventListener('focus',checkReminders);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkReminders()});
document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===current));({today:renderToday,timetable:renderTimetable,assignments:renderAssignments,study:renderStudy,planner:renderPlanner}[current]||renderToday)();bindCommon()}
function bindCommon(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>remove(b.dataset.type,b.dataset.del));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(b.dataset.edit,b.dataset.del));}
function renderToday(){title(data.settings.name?`Good ${greeting()}, ${data.settings.name}`:'Today');const now=new Date(), day=now.getDay(), date=now.toISOString().slice(0,10);const onBreak=data.holidays.some(h=>h.skipClasses!==false&&h.start<=date&&(h.end||h.start)>=date);const ev=data.events.filter(e=>(e.date===date||recursToday(e,day))&&!(onBreak&&e.recurring)).sort((a,b)=>a.start.localeCompare(b.start));const as=data.assignments.filter(a=>!a.done).sort((a,b)=>dt(a.due)-dt(b.due));const next=as[0];view.innerHTML=`<div class="desktop-two"><section class="stack">${next?`<div class="hero"><div><div class="eyebrow">Next deadline</div><h2>${esc(next.title)}</h2><p>${esc(subject(next.subjectId).name)} · ${dueText(next.due)}</p></div><div class="hero-value">${Math.max(0,Math.ceil((dt(next.due)-new Date())/86400000))}<small>d</small></div></div>`:`<div class="hero"><div><div class="eyebrow">Your day</div><h2>Ready when you are</h2><p>Add a class, deadline or goal.</p></div></div>`}<div class="grid two"><div class="card"><div class="eyebrow">Study streak</div><div class="big-number">${streak()} days</div><div class="meta">Sessions on consecutive days</div></div><div class="card water-card" id="waterCard" role="group" aria-label="Water intake"><div class="water-card-head"><div class="eyebrow">Water · tap</div><div class="water-count"><strong>${data.water}</strong><span>/${data.waterGoal}</span></div></div><div class="water-blocks" aria-label="${data.water} of ${data.waterGoal} glasses">${Array.from({length:data.waterGoal},(_,i)=>`<button class="water-block ${i<data.water?'filled':''}" data-water-index="${i}" aria-label="Set water count to ${i+1}"></button>`).join('')}</div><div class="water-hint">Tap a block to set the count. Tap the last filled block to subtract.</div></div></div><div class="section-head"><span class="section-title">Today's schedule</span><button class="link-btn" data-add="event">+ Add</button></div>${ev.length?`<div class="card">${ev.map(eventItem).join('')}</div>`:empty('classes or activities today','event')}</section><aside><div class="section-head"><span class="section-title">Assignments</span><button class="link-btn" data-add="assignment">+ Add</button></div>${as.length?`<div class="card">${as.slice(0,5).map(assignmentItem).join('')}</div>`:empty('assignments','assignment')}<div class="section-head"><span class="section-title">One goal</span><button class="link-btn" data-add="goal">+ Add</button></div>${data.goals.filter(g=>!g.done).length?`<div class="card">${esc(data.goals.find(g=>!g.done).title)}</div>`:empty('goals','goal')}</aside></div>`;document.querySelectorAll('[data-water-index]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.waterIndex)+1;data.water=data.water===n?n-1:n;save()})}
function greeting(){const h=new Date().getHours();return h<12?'morning':h<18?'afternoon':'evening'}
function streak(){const days=new Set(data.studySessions.map(s=>s.date));let n=0,d=new Date();while(days.has(d.toISOString().slice(0,10))){n++;d.setDate(d.getDate()-1)}return n}
function recursToday(e,day){if(!e.recurring||!e.days)return false;if(!e.days.includes(day))return false;const today=new Date(),start=new Date(e.date+'T12:00:00');if(today<start)return false;if(e.until&&today>new Date(e.until+'T23:59:00'))return false;const weeks=Math.floor((today-start)/604800000);return e.pattern!=='alternate'||weeks%2===0}
function eventItem(e){const s=subject(e.subjectId);return `<div class="item"><i class="dot" style="background:${s.colour||e.colour||'#e63d83'}"></i><div><div class="item-title">${esc(e.title)}</div><div class="meta">${esc(e.start)}${e.end?'–'+esc(e.end):''}${e.room?' · '+esc(e.room):''}</div></div><div class="list-actions"><button class="mini" data-edit="event" data-type="event" data-del="${e.id}">Edit</button><button class="mini" data-type="events" data-del="${e.id}">×</button></div></div>`}
function assignmentItem(a){const s=subject(a.subjectId);const done=a.steps?.filter(x=>x.done).length||0,total=a.steps?.length||0;return `<div class="item"><input type="checkbox" data-complete="${a.id}" ${a.done?'checked':''}><div><div class="item-title">${esc(a.title)}</div><div class="meta">${esc(s.code||s.name)} · ${dueText(a.due)}${a.weight?' · '+a.weight+'%':''}</div>${total?`<div class="progress"><i style="width:${done/total*100}%"></i></div>`:''}</div><div><span class="badge ${a.priority||'low'}">${a.priority||'low'}</span><div class="list-actions"><button class="mini" data-edit="assignment" data-del="${a.id}">Edit</button><button class="mini" data-type="assignments" data-del="${a.id}">×</button></div></div></div>`}
function renderTimetable(){title('Timetable');const days=['Mon','Tue','Wed','Thu','Fri'];let cells='<div class="head"></div>'+days.map(d=>`<div class="head">${d}</div>`).join('');for(let h=8;h<=18;h++){cells+=`<div>${String(h).padStart(2,'0')}:00</div>`;for(let d=1;d<=5;d++){const es=data.events.filter(e=>e.recurring&&e.days?.includes(d)&&Number(e.start?.slice(0,2))===h);cells+=`<div>${es.map(e=>{const s=subject(e.subjectId);return `<div class="class-block" style="border-color:${s.colour};background:color-mix(in srgb,${s.colour} 18%,var(--surface))" data-edit="event" data-del="${e.id}"><b>${esc(e.title)}</b><br>${esc(e.start)}</div>`}).join('')}</div>`}}view.innerHTML=`<div class="section-head"><span class="section-title">Recurring week</span><button class="primary" data-add="event">+ Class/event</button></div><div class="week-grid">${cells}</div><div class="section-head"><span class="section-title">Free block finder</span></div><div class="card">${freeBlocks()}</div><div class="section-head"><span class="section-title">All schedule items</span></div>${data.events.length?`<div class="card">${data.events.sort((a,b)=>a.start.localeCompare(b.start)).map(eventItem).join('')}</div>`:empty('schedule items','event')}`}
function freeBlocks(){const out=[];for(let d=1;d<=5;d++){const es=data.events.filter(e=>e.recurring&&e.days?.includes(d)).sort((a,b)=>a.start.localeCompare(b.start));let cursor='08:00';for(const e of es){if(e.start>cursor)out.push(`${['','Mon','Tue','Wed','Thu','Fri'][d]} ${cursor}–${e.start}`);if(e.end>cursor)cursor=e.end}if(cursor<'18:00')out.push(`${['','Mon','Tue','Wed','Thu','Fri'][d]} ${cursor}–18:00`)}return out.length?out.slice(0,8).map(x=>`<button class="chip" data-add="study-session">${x}</button>`).join(''):'Add recurring classes to reveal free blocks.'}
function renderAssignments(){title('Deadlines');view.innerHTML=`<div class="assignment-toolbar"><div class="view-switch"><button class="active" data-deadline-view="list">List</button><button data-deadline-view="calendar">Calendar</button></div><select id="deadlineCourse" aria-label="Filter deadlines by course"><option value="all">All courses</option>${data.subjects.map(c=>`<option value="${c.id}" ${deadlineCourse===c.id?'selected':''}>${esc(c.code?c.code+' · '+c.name:c.name)}</option>`).join('')}</select><button class="primary" id="globalAddAssignment">+ Assignment</button></div><div id="deadlineBody"></div>`;showDeadlineList('all');$('#globalAddAssignment').onclick=()=>openForm('assignment');$('#deadlineCourse').onchange=e=>{deadlineCourse=e.target.value;showDeadlineList('all')};document.querySelectorAll('[data-deadline-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-deadline-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');b.dataset.deadlineView==='calendar'?showDeadlineCalendar():showDeadlineList('all')})}
function deadlineItems(){return data.assignments.filter(a=>deadlineCourse==='all'||a.subjectId===deadlineCourse)}
function showDeadlineList(f){let xs=deadlineItems().sort((a,b)=>dt(a.due)-dt(b.due));if(f==='done')xs=xs.filter(x=>x.done);else if(f!=='all')xs=xs.filter(x=>x.priority===f&&!x.done);else xs=xs.filter(x=>!x.done);$('#deadlineBody').innerHTML=`<div class="chips deadline-filters">${['all','high','medium','low','done'].map((x,i)=>`<button class="chip ${x===f?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div>${xs.length?`<div class="card">${xs.map(assignmentItem).join('')}</div>`:empty('matching deadlines')}`;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>showDeadlineList(b.dataset.filter));bindCommon();document.querySelectorAll('[data-complete]').forEach(c=>c.onchange=()=>{const a=data.assignments.find(x=>x.id===c.dataset.complete);a.done=c.checked;save()})}
function showDeadlineCalendar(){const y=deadlineMonth.getFullYear(),m=deadlineMonth.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),start=(first.getDay()+6)%7,cells=[];for(let i=0;i<start;i++)cells.push('<div class="calendar-day outside"></div>');for(let d=1;d<=last.getDate();d++){const key=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,items=deadlineItems().filter(a=>String(a.due||'').slice(0,10)===key).sort((a,b)=>({high:0,medium:1,low:2}[a.priority||'low']-({high:0,medium:1,low:2}[b.priority||'low'])));cells.push(`<div class="calendar-day ${key===new Date().toISOString().slice(0,10)?'today-cell':''}"><div class="day-number">${d}</div>${items.slice(0,3).map(a=>{const c=subject(a.subjectId);return `<button class="deadline-pill ${a.priority||'low'}" data-edit="assignment" data-del="${a.id}" style="--course-colour:${c.colour}"><span></span>${esc(c.code||c.name||'Course')} · ${esc(a.title)}</button>`}).join('')}${items.length>3?`<button class="more-deadlines" data-date="${key}">+${items.length-3} more</button>`:''}</div>`)}while(cells.length%7)cells.push('<div class="calendar-day outside"></div>');const upcoming=deadlineItems().filter(a=>!a.done&&dt(a.due)>=new Date().setHours(0,0,0,0)).sort((a,b)=>dt(a.due)-dt(b.due)).slice(0,8);$('#deadlineBody').innerHTML=`<div class="calendar-head"><button class="icon-btn" id="prevMonth">‹</button><h2 class="serif">${new Intl.DateTimeFormat('en-CA',{month:'long',year:'numeric'}).format(first)}</h2><button class="icon-btn" id="nextMonth">›</button></div><div class="calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div>${x}</div>`).join('')}</div><div class="deadline-calendar">${cells.join('')}</div><div class="section-head"><span class="section-title">Upcoming deadlines</span></div>${upcoming.length?`<div class="card">${upcoming.map(assignmentItem).join('')}</div>`:empty('upcoming deadlines')}`;$('#prevMonth').onclick=()=>{deadlineMonth=new Date(y,m-1,1);showDeadlineCalendar()};$('#nextMonth').onclick=()=>{deadlineMonth=new Date(y,m+1,1);showDeadlineCalendar()};document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>showDayDeadlines(b.dataset.date));bindCommon()}
function showDayDeadlines(date){const xs=deadlineItems().filter(a=>String(a.due||'').slice(0,10)===date).sort((a,b)=>dt(a.due)-dt(b.due));showSheet(new Intl.DateTimeFormat('en-CA',{weekday:'long',month:'long',day:'numeric'}).format(new Date(date+'T12:00:00')),xs.length?`<div class="card">${xs.map(assignmentItem).join('')}</div>`:empty('deadlines'));bindCommon()}
function renderStudy(){title('Study');const today=new Date().toISOString().slice(0,10),todayMins=data.studySessions.filter(x=>x.date===today).reduce((a,b)=>a+Number(b.minutes||0),0),mins=Math.floor(timer.left/60),secs=timer.left%60;view.innerHTML=`<div class="study-summary"><div class="card"><div class="eyebrow">Focused today</div><div class="big-number">${Math.floor(todayMins/60)}h ${todayMins%60}m</div></div><div class="card"><div class="eyebrow">Study streak</div><div class="big-number">${streak()} days</div></div></div><div class="study-menu"><button style="--feature:#ef3d86" data-study-panel="timer"><span>◷</span><div><b>Focus timer</b><small>Pomodoro sessions that log your hours</small></div><i>›</i></button><button style="--feature:#60c796" data-study-panel="modules"><span>▤</span><div><b>Module hubs</b><small>Notes, readings and decks by course</small></div><i>›</i></button><button style="--feature:#aa8ce2" data-study-panel="revision"><span>◎</span><div><b>Revision hub</b><small>Rate topics and revise weak areas first</small></div><i>›</i></button><button style="--feature:#e4bd50" data-study-panel="flashcards"><span>▦</span><div><b>Flashcards</b><small>Course decks and spaced review</small></div><i>›</i></button><button style="--feature:#ef9d75" data-study-panel="free"><span>▥</span><div><b>Free-block finder</b><small>Start a focus session in timetable gaps</small></div><i>›</i></button><button style="--feature:#9d88da" data-study-panel="plan"><span>＋</span><div><b>Plan a study session</b><small>Schedule focused time for a course</small></div><i>›</i></button></div><div id="studyPanel"></div>`;document.querySelectorAll('[data-study-panel]').forEach(b=>b.onclick=()=>showStudyPanel(b.dataset.studyPanel));}
function showStudyPanel(kind){const box=$('#studyPanel');if(kind==='timer'){box.innerHTML=`<div class="section-head"><span class="section-title">Focus timer</span></div><div class="timer card"><div class="timer-ring"><div><div class="timer-time">${String(Math.floor(timer.left/60)).padStart(2,'0')}:${String(timer.left%60).padStart(2,'0')}</div><div class="meta">focused time</div></div></div><div class="chips">${[15,25,45,60].map(x=>`<button class="chip" data-min="${x}">${x}m</button>`).join('')}</div><div class="actions"><button class="primary" id="timerStart">${timer.running?'Pause':'Start'}</button><button class="secondary" id="timerReset">Reset</button></div></div>`;$('#timerStart').onclick=toggleTimer;$('#timerReset').onclick=()=>{clearInterval(timer.id);timer={left:1500,total:1500,running:false,id:null};showStudyPanel('timer')};document.querySelectorAll('[data-min]').forEach(b=>b.onclick=()=>{timer.left=timer.total=Number(b.dataset.min)*60;showStudyPanel('timer')});return}if(kind==='free'){const blocks=freeBlockData();box.innerHTML=`<div class="section-head"><span class="section-title">Free blocks this week</span></div>${blocks.length?blocks.map(x=>`<div class="card free-block"><div><b>${x.label}</b><div class="meta">${x.hours} free · Suggested: ${esc(x.course)}</div></div><button class="primary" data-start-focus>Start focus session</button></div>`).join(''):empty('free blocks')}`;document.querySelectorAll('[data-start-focus]').forEach(x=>x.onclick=()=>showStudyPanel('timer'));return}if(kind==='modules'){box.innerHTML=`<div class="section-head"><span class="section-title">Module hubs</span></div>${data.subjects.length?data.subjects.map(c=>`<div class="card coloured-module" style="--course:${c.colour}"><div><div class="eyebrow">${esc(c.code)}</div><h3>${esc(c.name)}</h3><div class="meta">${data.notes.filter(n=>n.subjectId===c.id).length} notes · ${data.readings.filter(n=>n.subjectId===c.id).length} readings · ${data.decks.filter(n=>n.subjectId===c.id).length} decks</div></div></div>`).join(''):empty('courses')}`;return}if(kind==='revision'){box.innerHTML=`<div class="section-head"><span class="section-title">Revision topics</span><button class="primary" id="addTopic">+ Topic</button></div>${data.revisionTopics.length?data.revisionTopics.map(t=>{const c=subject(t.subjectId);return `<div class="card revision-row" style="--course:${c.colour}"><div><b>${esc(t.title)}</b><div class="meta">${esc(c.code||c.name)}</div></div><span class="readiness ${t.level}">${t.level}</span><button class="mini" data-type="revisionTopics" data-del="${t.id}">×</button></div>`}).join(''):empty('revision topics')}`;$('#addTopic').onclick=openRevisionTopic;bindCommon();return}if(kind==='flashcards'){box.innerHTML=`<div class="section-head"><span class="section-title">Flashcard decks</span><button class="primary" data-add="deck">+ Deck</button></div>${data.decks.length?data.decks.map(d=>{const c=subject(d.subjectId);return `<div class="card coloured-module" style="--course:${c.colour}"><div class="eyebrow">${esc(c.code||c.name)}</div><h3>${esc(d.name)}</h3><div class="meta">${d.cards?.length||0} cards</div></div>`}).join(''):empty('flashcard decks')}`;bindCommon();return}if(kind==='plan'){openForm('study-session');return}}
function openRevisionTopic(){showSheet('Revision topic',`<form class="form" id="topicForm"><div class="field"><label>Topic</label><input name="title" required></div><div class="field"><label>Course</label><select name="subjectId">${data.subjects.map(c=>`<option value="${c.id}">${esc(c.code||c.name)}</option>`).join('')}</select></div><div class="field"><label>Readiness</label><select name="level"><option>weak</option><option>okay</option><option>confident</option></select></div><button class="primary">Save topic</button><button class="secondary" type="button" data-close>Cancel</button></form>`);$('#topicForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);data.revisionTopics.push({id:id(),title:f.get('title'),subjectId:f.get('subjectId'),level:f.get('level')});closeSheet();save();setTimeout(()=>{current='study';render();showStudyPanel('revision')})}}
function freeBlockData(){const out=[];for(let d=1;d<=5;d++){const es=data.events.filter(e=>e.recurring&&e.days?.includes(d)).sort((a,b)=>a.start.localeCompare(b.start));let cur='08:00';for(const e of es){if(e.start>cur)out.push(makeBlock(d,cur,e.start));if(e.end>cur)cur=e.end}if(cur<'18:00')out.push(makeBlock(d,cur,'18:00'))}return out.slice(0,10)}
function makeBlock(day,start,end){const mins=(Number(end.slice(0,2))*60+Number(end.slice(3)))-(Number(start.slice(0,2))*60+Number(start.slice(3))),course=data.subjects[0];return{label:`${['','Mon','Tue','Wed','Thu','Fri'][day]} · ${start} to ${end}`,hours:`${Math.floor(mins/60)}h${mins%60?' '+mins%60+'m':''}`,course:course?.name||'Choose a course'}}
function toggleTimer(){if(timer.running){clearInterval(timer.id);timer.running=false;render()}else{timer.running=true;timer.id=setInterval(()=>{timer.left--;if(timer.left<=0){clearInterval(timer.id);timer.running=false;data.studySessions.push({id:id(),date:new Date().toISOString().slice(0,10),minutes:timer.total/60});save();toast('Focus session complete');timer.left=timer.total}if(current==='study')renderStudy()},1000);render()}}
function renderPlanner(){title('Planner');const sem=[...data.semesters].sort((a,b)=>dt(b.start)-dt(a.start));view.innerHTML=`<div class="planner-head"><div><div class="eyebrow">Academic archive</div><h2 class="serif">Semesters</h2></div><button class="primary" data-add="semester">+ Semester</button></div>${sem.length?`<div class="grid cards">${sem.map(x=>`<button class="card semester-card semester-link" data-sem="${x.id}" style="border-top:8px solid ${x.colour}"><div class="eyebrow">${fmt(x.start)} – ${fmt(x.end)}</div><h2 class="serif">${esc(x.name)}</h2><div class="meta">${data.subjects.filter(c=>c.semesterId===x.id).length} courses</div><div class="big-number">${weightedAvg(data.grades.filter(g=>g.semesterId===x.id))||'—'}</div></button>`).join('')}</div>`:empty('semesters')}`;bindCommon();document.querySelectorAll('[data-sem]').forEach(x=>x.onclick=()=>openSemester(x.dataset.sem))}
function openSemester(id){const sem=data.semesters.find(x=>x.id===id);if(!sem)return;title(sem.name);view.innerHTML=`<button class="back-btn" id="backPlanner">‹ All semesters</button><div class="semester-banner" style="--semester:${sem.colour}"><div><div class="eyebrow">${fmt(sem.start)} – ${fmt(sem.end)}</div><h2 class="serif">${esc(sem.name)}</h2></div><button class="secondary" data-edit="semester" data-del="${sem.id}">Edit</button></div><div class="subnav"><button class="active" data-st="courses">Courses</button><button data-st="holidays">Holidays</button><button data-st="instructors">Instructors</button><button data-st="activities">Activities</button></div><div id="semesterBody"></div>`;showSemester('courses',sem);$('#backPlanner').onclick=render;document.querySelectorAll('[data-st]').forEach(x=>x.onclick=()=>{document.querySelectorAll('[data-st]').forEach(y=>y.classList.remove('active'));x.classList.add('active');showSemester(x.dataset.st,sem)});bindCommon()}
function showSemester(tab,sem){const box=$('#semesterBody');if(tab==='courses'){const cs=data.subjects.filter(x=>x.semesterId===sem.id);box.innerHTML=`<div class="section-head"><span class="section-title">Courses</span><button class="primary" id="addCourse">+ Course</button></div>${cs.length?`<div class="grid cards">${cs.map(courseCard).join('')}</div>`:empty('courses')}`;$('#addCourse').onclick=()=>openScoped('subject',sem.id);document.querySelectorAll('[data-course]').forEach(x=>x.onclick=()=>openCourse(x.dataset.course));return}const map={holidays:['holidays','holiday'],instructors:['professors','professor'],activities:['activities','activity']},[coll,kind]=map[tab],xs=data[coll].filter(x=>!x.semesterId||x.semesterId===sem.id);box.innerHTML=`<div class="section-head"><span class="section-title">${tab}</span><button class="primary" id="addScoped">+ ${kind==='professor'?'Instructor':kind}</button></div>${xs.length?`<div class="grid cards">${xs.map(x=>genericCard(x,coll)).join('')}</div>`:empty(tab)}`;$('#addScoped').onclick=()=>openScoped(kind,sem.id);bindCommon()}
function courseCard(c){const avg=weightedAvg(data.grades.filter(g=>g.subjectId===c.id));return `<button class="card course-card" data-course="${c.id}" style="border-left:7px solid ${c.colour}"><div><div class="eyebrow">${esc(c.code)}</div><h3>${esc(c.name)}</h3><div class="meta">${esc(c.credits||'0')} credits</div></div><div class="big-number">${avg||'—'}${avg?'%':''}</div></button>`}
function openCourse(id){const c=data.subjects.find(x=>x.id===id);if(!c)return;title(c.code||c.name);view.innerHTML=`<button class="back-btn" id="backSemester">‹ Semester</button><div class="course-banner" style="--course:${c.colour}"><div><div class="eyebrow">${esc(c.code)}</div><h2 class="serif">${esc(c.name)}</h2></div><button class="secondary" data-edit="subject" data-del="${c.id}">Edit</button></div><div class="subnav"><button class="active" data-ct="overview">Overview</button><button data-ct="assignments">Assignments</button><button data-ct="exams">Exams</button><button data-ct="grades">Grades</button><button data-ct="notes">Notes</button></div><div id="courseBody"></div>`;showCourse('overview',c);$('#backSemester').onclick=()=>openSemester(c.semesterId);document.querySelectorAll('[data-ct]').forEach(x=>x.onclick=()=>{document.querySelectorAll('[data-ct]').forEach(y=>y.classList.remove('active'));x.classList.add('active');showCourse(x.dataset.ct,c)});bindCommon()}
function showCourse(tab,c){const box=$('#courseBody'),as=data.assignments.filter(x=>x.subjectId===c.id),gs=data.grades.filter(x=>x.subjectId===c.id),avg=weightedAvg(gs);if(tab==='overview'){box.innerHTML=`<div class="metric-grid"><div class="card"><div class="eyebrow">Current grade</div><div class="big-number">${avg||'—'}${avg?'%':''}</div></div><div class="card"><div class="eyebrow">GPA estimate</div><div class="big-number">${gpa(avg)}</div></div><div class="card"><div class="eyebrow">Canadian letter</div><div class="big-number">${letter(avg)}</div></div><div class="card"><div class="eyebrow">Projected</div><div class="big-number">${projected(c.id)||'—'}</div></div></div>${gradeTools(c,gs)}`;setTimeout(drawCourseChart);return}if(tab==='assignments'||tab==='exams'){const kind=tab==='exams'?'exam':'assignment',xs=as.filter(x=>(x.kind||'assignment')===kind).sort((a,b)=>dt(a.due)-dt(b.due));box.innerHTML=`<div class="section-head"><span class="section-title">${tab}</span><button class="primary" id="addAssessment">+ ${kind}</button></div>${xs.length?`<div class="card">${xs.map(assignmentItem).join('')}</div>`:empty(tab)}`;$('#addAssessment').onclick=()=>openScoped('assignment',c.semesterId,c.id,kind);bindCommon();return}if(tab==='grades'){box.innerHTML=`<div class="section-head"><span class="section-title">Grades</span><button class="primary" id="addGrade">+ Grade</button></div>${gs.length?`<div class="grid cards">${gs.map(gradeCard).join('')}</div>`:empty('grades')}${gradeTools(c,gs)}`;$('#addGrade').onclick=()=>openScoped('grade',c.semesterId,c.id);bindCommon();setTimeout(drawCourseChart);return}const ns=data.notes.filter(x=>x.subjectId===c.id);box.innerHTML=`<div class="section-head"><span class="section-title">Notes</span><button class="primary" id="addNote">+ Note</button></div>${ns.length?ns.map(n=>`<div class="card"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></div>`).join(''):empty('notes')}`;$('#addNote').onclick=()=>openScoped('note',c.semesterId,c.id)}
function openScoped(kind,semesterId,courseId,assessmentKind){openForm(kind);setTimeout(()=>{const f=$('#editForm');if(!f)return;f.onsubmit=((original)=>e=>{const fd=new FormData(f);original(e);const coll={subject:'subjects',assignment:'assignments',grade:'grades',note:'notes',holiday:'holidays',professor:'professors',activity:'activities'}[kind],obj=data[coll][data[coll].length-1];if(obj){obj.semesterId=semesterId;if(courseId)obj.subjectId=courseId;if(assessmentKind)obj.kind=assessmentKind;localStorage.setItem(KEY,JSON.stringify(data));setTimeout(()=>courseId?openCourse(courseId):openSemester(semesterId),0)}})(f.onsubmit)},0)}
function projected(id){const gs=data.grades.filter(g=>g.subjectId===id),as=data.assignments.filter(a=>a.subjectId===id&&a.target),w=gs.reduce((s,g)=>s+Number(g.weight||0),0)+as.reduce((s,a)=>s+Number(a.weight||0),0);return w?((gs.reduce((s,g)=>s+Number(g.score)*Number(g.weight||0),0)+as.reduce((s,a)=>s+Number(a.target)*Number(a.weight||0),0))/w).toFixed(1)+'%':null}
function gpa(v){v=Number(v);if(!v)return'—';return(v>=90?4:v>=85?3.9:v>=80?3.7:v>=77?3.3:v>=73?3:v>=70?2.7:v>=67?2.3:v>=63?2:v>=60?1.7:v>=57?1.3:v>=53?1:v>=50?.7:0).toFixed(1)}
function gradeTools(c,gs){return `<div class="card grade-tools"><div class="section-title">Grade projection</div><div class="form"><div class="field"><label>Desired final percentage</label><input id="target" type="number"></div><div class="field"><label>Remaining course weight (%)</label><input id="remaining" type="number"></div><button class="primary" id="calcNeed">Calculate required grade</button><div id="needResult"></div></div><div class="section-head"><span class="section-title">Grade trend</span></div><canvas id="gradeChart" width="700" height="220" data-course="${c.id}"></canvas></div>`}
function drawCourseChart(){const c=$('#gradeChart');if(!c)return;const gs=data.grades.filter(g=>g.subjectId===c.dataset.course).sort((a,b)=>dt(a.date)-dt(b.date)),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.strokeStyle='#e63d83';ctx.lineWidth=5;ctx.beginPath();gs.forEach((g,i)=>{const x=45+i*(620/Math.max(1,gs.length-1)),y=200-Number(g.score)*1.7;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();$('#calcNeed').onclick=()=>{const t=Number($('#target').value),r=Number($('#remaining').value),cur=Number(weightedAvg(gs)||0),need=(t*100-cur*(100-r))/r;$('#needResult').innerHTML=`<div class="result-box">Required: <strong>${Number.isFinite(need)?need.toFixed(1):'—'}%</strong></div>`}}
function subjectCard(x){return courseCard(x)}
function gradeCard(x){return `<div class="card"><div class="eyebrow">${fmt(x.date)}</div><h3>${esc(x.title)}</h3><div class="big-number">${x.score}%</div><div class="meta">Weight ${x.weight}%</div><button class="mini" data-type="grades" data-del="${x.id}">Delete</button></div>`}
function genericCard(x,t){return `<div class="card"><h3>${esc(x.name||x.title)}</h3><div class="meta">${esc([x.role,x.email,x.officeHours,x.start&&fmt(x.start),x.joined&&fmt(x.joined)].filter(Boolean).join(' · '))}</div><button class="mini" data-type="${t}" data-del="${x.id}">Delete</button></div>`}
function weightedAvg(gs){if(!gs.length)return null;const w=gs.reduce((s,g)=>s+Number(g.weight||0),0);if(!w)return (gs.reduce((s,g)=>s+Number(g.score),0)/gs.length).toFixed(1);return (gs.reduce((s,g)=>s+Number(g.score)*Number(g.weight),0)/w).toFixed(1)}
function gradeSummary(){const avg=weightedAvg(data.grades);return `<div class="section-head"><span class="section-title">Progress & target calculator</span></div><div class="card"><div class="grid two"><div><div class="eyebrow">Current weighted grade</div><div class="big-number">${avg??'—'}${avg?'%':''}</div></div><div><div class="eyebrow">Canadian letter</div><div class="big-number">${letter(avg)}</div></div></div><div class="form" style="margin-top:15px"><div class="field"><label>Desired final percentage</label><input id="target" type="number" min="0" max="100"></div><div class="field"><label>Remaining course weight (%)</label><input id="remaining" type="number" min="1" max="100"></div><button class="primary" id="calcNeed">Calculate required grade</button><div id="needResult"></div></div><div class="section-head"><span class="section-title">Grade trend</span></div><canvas id="gradeChart" width="700" height="220"></canvas></div>`}
function letter(v){v=Number(v);if(!Number.isFinite(v))return '—';return v>=90?'A+':v>=85?'A':v>=80?'A−':v>=77?'B+':v>=73?'B':v>=70?'B−':v>=67?'C+':v>=63?'C':v>=60?'C−':v>=57?'D+':v>=53?'D':v>=50?'D−':'F'}
function drawChart(){const c=$('#gradeChart');if(!c)return;const ctx=c.getContext('2d'),gs=[...data.grades].sort((a,b)=>dt(a.date)-dt(b.date));ctx.clearRect(0,0,c.width,c.height);ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--line');for(let y=20;y<210;y+=45){ctx.beginPath();ctx.moveTo(35,y);ctx.lineTo(680,y);ctx.stroke()}if(gs.length){ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--accent');ctx.lineWidth=5;ctx.beginPath();gs.forEach((g,i)=>{const x=45+i*(620/Math.max(1,gs.length-1)),y=200-Number(g.score)*1.7;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}const b=$('#calcNeed');if(b)b.onclick=()=>{const target=Number($('#target').value),rem=Number($('#remaining').value),cur=Number(avgValue());const completed=100-rem,need=(target*100-cur*completed)/rem;$('#needResult').innerHTML=`<div class="card">You need <strong>${Number.isFinite(need)?need.toFixed(1):'—'}%</strong> on the remaining work.</div>`}}
function avgValue(){return weightedAvg(data.grades)||0}
function remove(type,itemId){if(!confirm('Delete this item?'))return;data[type]=data[type].filter(x=>x.id!==itemId);save();toast('Deleted')}
const templates={Essay:['Read the brief and rubric','Gather sources','Outline the argument','Write first draft','Add citations and references','Proofread and submit'],Presentation:['Define message','Research','Create slide outline','Build slides','Rehearse','Submit'], 'Lab Report':['Review lab notes','Organize data','Write methods','Analyze results','Write discussion','Proofread and submit'],'Group Project':['Confirm roles','Set milestones','Complete your section','Review as a group','Rehearse','Submit'],'Exam Revision':['List topics','Rate weak areas','Build revision plan','Practise questions','Review mistakes','Final recap']};
function openForm(kind,editId){const plural={subject:'subjects',assignment:'assignments',event:'events',semester:'semesters',grade:'grades',professor:'professors',holiday:'holidays',activity:'activities','important-day':'important',goal:'goals',note:'notes',reading:'readings',deck:'decks','study-session':'studySessions'}[kind];const item=editId?data[plural]?.find(x=>x.id===editId):null;const names={subject:'Subject',assignment:'Assignment',event:'Class or event',semester:'Semester',grade:'Grade',professor:'Professor',holiday:'Holiday or reading week',activity:'Club or activity','important-day':'Important day',goal:'Goal',note:'Module note',reading:'Reading',deck:'Flashcard deck','study-session':'Study session'};let fields='';const v=k=>esc(item?.[k]??'');const subjectSelect=`<div class="field"><label>Subject</label><input name="subjectText" value="${item?esc(subject(item.subjectId).name):''}"></div>`;
if(kind==='subject')fields=`${f('name','Subject name',v('name'))}${f('code','Course code',v('code'))}${f('credits','Credits',v('credits'),'number')}${f('colour','Custom colour',v('colour')||'#e63d83','color')}`;
if(kind==='assignment')fields=`${f('title','Assignment name',v('title'))}${subjectSelect}<div class="field"><label>Template</label><select name="template"><option value="">Blank</option>${Object.keys(templates).map(x=>`<option>${x}</option>`).join('')}</select></div>${f('due','Deadline',v('due'),'datetime-local')}${f('weight','Weight (%)',v('weight'),'number')}<div class="field"><label>Priority</label><div class="segmented">${['low','medium','high'].map(x=>`<label><input type="radio" name="priority" value="${x}" ${(item?.priority||'medium')===x?'checked':''}>${x}</label>`).join('')}</div></div>${f('target','Target grade (%)',v('target'),'number')}<div class="field"><label>Reminder</label><select name="reminderMinutes"><option value="">No reminder</option><option value="60" ${item?.reminderMinutes==='60'?'selected':''}>1 hour before</option><option value="1440" ${item?.reminderMinutes==='1440'?'selected':''}>1 day before</option><option value="2880" ${item?.reminderMinutes==='2880'?'selected':''}>2 days before</option><option value="10080" ${item?.reminderMinutes==='10080'?'selected':''}>1 week before</option></select></div>${ta('notes','Notes',v('notes'))}`;
if(kind==='event')fields=`${f('title','Class, event or activity',v('title'))}${subjectSelect}${f('date','First date',v('date')||new Date().toISOString().slice(0,10),'date')}${f('start','Start time',v('start'),'time')}${f('end','End time',v('end'),'time')}${f('room','Room or location',v('room'))}${f('professor','Professor or facilitator',v('professor'))}<label class="checkrow"><input type="checkbox" name="recurring" ${item?.recurring?'checked':''}> Recurring</label><div class="field"><label>Repeat days</label><div class="chips">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((x,i)=>`<label class="chip"><input type="checkbox" name="days" value="${i}" ${item?.days?.includes(i)?'checked':''}> ${x}</label>`).join('')}</div></div><div class="field"><label>Pattern</label><select name="pattern"><option value="weekly">Every week</option><option value="alternate" ${item?.pattern==='alternate'?'selected':''}>Alternate weeks</option></select></div>${f('until','Repeat until',v('until'),'date')}`;
if(kind==='semester')fields=`${f('name','Semester name',v('name'))}${f('start','Start date',v('start'),'date')}${f('end','End date',v('end'),'date')}${f('colour','Semester colour',v('colour')||'#4f9b77','color')}`;
if(kind==='grade')fields=`${f('title','Assessment name',v('title'))}${subjectSelect}<div class="field"><label>Semester</label><select name="semesterId"><option value=""></option>${data.semesters.map(s=>`<option value="${s.id}" ${item?.semesterId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>${f('score','Score (%)',v('score'),'number')}${f('weight','Weight (%)',v('weight'),'number')}${f('date','Date received',v('date'),'date')}`;
if(kind==='professor')fields=`${f('name','Professor name',v('name'))}${f('role','Title or department',v('role'))}${f('email','Email',v('email'),'email')}${f('phone','Phone',v('phone'),'tel')}${f('office','Office location',v('office'))}${f('officeHours','Office hours',v('officeHours'))}${ta('notes','Notes',v('notes'))}`;
if(kind==='holiday')fields=`${f('name','Holiday or break name',v('name'))}${f('start','Start date',v('start'),'date')}${f('end','End date',v('end'),'date')}<label class="checkrow"><input type="checkbox" name="skipClasses" ${item?.skipClasses!==false?'checked':''}> Hide classes during this break</label><label class="checkrow"><input type="checkbox" name="shiftSchedule" ${item?.shiftSchedule?'checked':''}> Shift schedule after break</label>`;
if(kind==='activity')fields=`${f('name','Club or activity name',v('name'))}${f('role','Role',v('role'))}${f('joined','Date joined',v('joined'),'date')}${f('left','Date left',v('left'),'date')}${f('hours','Hours per week',v('hours'),'number')}${f('contact','Contact or website',v('contact'))}${ta('notes','Achievements and notes',v('notes'))}`;
if(kind==='important-day')fields=`${f('title','Day to remember',v('title'))}${f('date','Date',v('date'),'date')}${ta('notes','Notes',v('notes'))}`;
if(kind==='goal')fields=`${f('title','Goal',v('title'))}${f('date','Target date',v('date'),'date')}`;
if(['note','reading','deck'].includes(kind))fields=`${subjectSelect}${f(kind==='note'?'title':kind==='reading'?'title':'name',kind==='note'?'Note title':kind==='reading'?'Reading title':'Deck name',v(kind==='deck'?'name':'title'))}${ta(kind==='note'?'body':'notes',kind==='note'?'Notes':'Details',v(kind==='note'?'body':'notes'))}`;
if(kind==='study-session')fields=`${f('date','Date',v('date')||new Date().toISOString().slice(0,10),'date')}${f('minutes','Minutes',v('minutes')||25,'number')}${subjectSelect}`;
showSheet(names[kind]||'Add',`<form class="form" id="editForm">${fields}<div class="actions"><button class="primary" type="submit">Save</button><button class="secondary" type="button" data-close>Cancel</button></div></form>`);$('#editForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target), obj=item?{...item}:{id:id()};for(const [k,val] of fd)if(k!=='days'&&k!=='subjectText')obj[k]=val;for(const c of e.target.querySelectorAll('input[type=checkbox]:not([name=days])'))obj[c.name]=c.checked;if(kind==='event')obj.days=fd.getAll('days').map(Number);const st=fd.get('subjectText')?.trim();if(st){let s=data.subjects.find(x=>x.name.toLowerCase()===st.toLowerCase()||x.code.toLowerCase()===st.toLowerCase());if(!s){s={id:id(),name:st,code:'',credits:'',colour:palette(data.subjects.length)};data.subjects.push(s)}obj.subjectId=s.id}if(kind==='assignment'&&!item&&fd.get('template'))obj.steps=templates[fd.get('template')].map(title=>({id:id(),title,done:false}));if(item)Object.assign(item,obj);else data[plural].push(obj);closeSheet();save();toast('Saved')}}
function f(name,label,value,type='text'){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${value}"></div>`}function ta(name,label,value){return `<div class="field"><label>${label}</label><textarea name="${name}">${value}</textarea></div>`}function palette(i){return ['#e63d83','#79c69a','#bea9e8','#efb980','#e8cf73','#91b8e2'][i%6]}
function showSheet(heading,body){root.innerHTML=`<div class="sheet-backdrop" role="presentation"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(heading)}"><div class="grab"></div><div class="sheet-head"><h2>${esc(heading)}</h2><button class="close" data-close aria-label="Close">×</button></div>${body}</section></div>`;root.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeSheet);root.querySelector('.sheet-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeSheet()};let y=0;const sh=root.querySelector('.sheet');sh.addEventListener('touchstart',e=>y=e.touches[0].clientY,{passive:true});sh.addEventListener('touchend',e=>{if(e.changedTouches[0].clientY-y>100&&sh.scrollTop===0)closeSheet()},{passive:true});document.addEventListener('keydown',escClose,{once:true});setTimeout(()=>root.querySelector('input,textarea,select')?.focus(),100)}
function escClose(e){if(e.key==='Escape')closeSheet()}function closeSheet(){root.innerHTML=''}
function openQuick(){showSheet('Quick add',`<div class="quick-grid">${[['assignment','Assignment'],['event','Class or event'],['study-session','Study session'],['goal','Goal'],['grade','Grade'],['activity','Club/activity'],['important-day','Important day'],['note','Note']].map(x=>`<button data-quick="${x[0]}">+ ${x[1]}</button>`).join('')}</div>`);document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>openForm(b.dataset.quick))}
function openSettings(){showSheet('Settings',`<div class="settings-home"><button data-settings-page="general"><span class="settings-icon pink">⌁</span><div><b>General</b><small>Time steps, class duration and working days</small></div><i>›</i></button><button data-settings-page="notifications"><span class="settings-icon green">◉</span><div><b>Notifications</b><small>Class, exam and deadline reminders</small></div><i>›</i></button><button data-settings-page="appearance"><span class="settings-icon purple">◐</span><div><b>Appearance</b><small>Theme, Today pane and calendar markers</small></div><i>›</i></button><button data-settings-page="wellness"><span class="settings-icon yellow">◇</span><div><b>Wellness</b><small>Water goal and study preferences</small></div><i>›</i></button><button data-settings-page="data"><span class="settings-icon coral">⇄</span><div><b>Data and backup</b><small>Export, import or erase local planner data</small></div><i>›</i></button></div>`);document.querySelectorAll('[data-settings-page]').forEach(b=>b.onclick=()=>showSettingsPage(b.dataset.settingsPage))}
function showSettingsPage(page){const defaults={timeStep:'5',classDuration:'60',workingDays:'Mon–Fri',assignmentLead:'10080',examLead:'20160',classLead:'15',onlineLead:'0',showOverdue:true,showExamsAhead:'14',multipleDots:true,colouredDots:true};data.settings={...defaults,...data.settings};const back=`<button class="settings-back" id="settingsBack">‹ Settings</button>`;let body='';if(page==='general')body=`${settingsSection('Time picker step',selectRow('Time step','timeStep',[['1','1 minute'],['5','5 minutes'],['15','15 minutes']],data.settings.timeStep))}${settingsSection('Schedule',selectRow('Class duration','classDuration',[['30','30 minutes'],['60','1 hour'],['90','1 hour 30 minutes'],['120','2 hours']],data.settings.classDuration)+selectRow('Working days','workingDays',[['Mon–Fri','Monday–Friday'],['Mon–Sat','Monday–Saturday'],['Every day','Every day']],data.settings.workingDays))}${settingsSection('Assignments',selectRow('Default due-date reminder','assignmentLead',[['1440','1 day ahead'],['2880','2 days ahead'],['10080','1 week ahead']],data.settings.assignmentLead))}`;if(page==='notifications')body=`${settingsSection('Permission',`<div class="settings-row"><div><b>System notifications</b><small id="notificationStatus">${notificationStatusText()}</small></div><button class="toggle-action" id="enableNotifications">Enable</button></div>`)}${settingsSection('Classes',toggleRow('Class notifications','classNotifications',data.settings.classNotifications!==false)+selectRow('Classes','classLead',[['5','5 minutes before'],['15','15 minutes before'],['30','30 minutes before'],['60','1 hour before']],data.settings.classLead)+selectRow('Online classes','onlineLead',[['0','On due date/time'],['15','15 minutes before'],['60','1 hour before']],data.settings.onlineLead))}${settingsSection('Exams',toggleRow('Exam notifications','examNotifications',data.settings.examNotifications!==false)+selectRow('Exams','examLead',[['1440','1 day before'],['10080','1 week before'],['20160','2 weeks before']],data.settings.examLead))}${settingsSection('Quiet hours',timeRow('Start','quietStart',data.notificationSettings?.quietStart||'22:00')+timeRow('End','quietEnd',data.notificationSettings?.quietEnd||'07:00'))}<button class="secondary settings-test" id="testNotification">Send test notification</button>`;if(page==='appearance')body=`${settingsSection('Theme',selectRow('Appearance','theme',[['auto','Automatic'],['light','Light'],['dark','Dark']],data.theme))}${settingsSection('Today pane',toggleRow('Overdue assignments','showOverdue',data.settings.showOverdue)+selectRow('Assignments due','assignmentsAhead',[['3','3 days'],['5','5 days'],['7','1 week'],['14','2 weeks']],data.settings.assignmentsAhead||'5')+selectRow('Show exams','showExamsAhead',[['7','1 week ahead'],['14','2 weeks ahead'],['30','1 month ahead']],data.settings.showExamsAhead))}${settingsSection('Calendar',toggleRow('Multiple dots','multipleDots',data.settings.multipleDots)+toggleRow('Coloured dots','colouredDots',data.settings.colouredDots))}`;if(page==='wellness')body=`${settingsSection('Water',numberRow('Daily water goal','waterGoal',data.waterGoal,1,24))}${settingsSection('Study',selectRow('Default focus session','focusLength',[['15','15 minutes'],['25','25 minutes'],['45','45 minutes'],['60','60 minutes']],data.settings.focusLength||'25'))}`;if(page==='data')body=`${settingsSection('Local data',`<button class="settings-wide" id="exportBtn">Export backup <span>›</span></button><label class="settings-wide">Import backup <span>›</span><input id="importFile" type="file" accept="application/json" hidden></label>`)}<button class="danger settings-wide danger-wide" id="clearBtn">Erase all local data</button>`;showSheet(page[0].toUpperCase()+page.slice(1),`${back}<form id="settingsPageForm" class="settings-page">${body}<button class="primary settings-save" type="submit">Save settings</button></form>`);$('#settingsBack').onclick=openSettings;const form=$('#settingsPageForm');form.onsubmit=e=>{e.preventDefault();const fd=new FormData(form);for(const [k,v]of fd)data.settings[k]=v;form.querySelectorAll('input[type=checkbox]').forEach(c=>data.settings[c.name]=c.checked);if(fd.has('theme'))data.theme=fd.get('theme');if(fd.has('waterGoal'))data.waterGoal=Math.max(1,Number(fd.get('waterGoal'))||8);data.notificationSettings={...(data.notificationSettings||{}),quietStart:fd.get('quietStart')||data.notificationSettings?.quietStart||'22:00',quietEnd:fd.get('quietEnd')||data.notificationSettings?.quietEnd||'07:00'};closeSheet();save();toast('Settings saved')};$('#enableNotifications')?.addEventListener('click',enableNotifications);$('#testNotification')?.addEventListener('click',()=>sendPlannerNotification('Study Bloom reminders','Notifications are working on this device.','test-'+Date.now()));$('#exportBtn')?.addEventListener('click',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='study-bloom-backup.json';a.click()});$('#importFile')?.addEventListener('change',e=>{const r=new FileReader();r.onload=()=>{try{data={...structuredClone(blank),...JSON.parse(r.result)};closeSheet();save();toast('Backup imported')}catch{toast('Could not import backup')}};r.readAsText(e.target.files[0])});$('#clearBtn')?.addEventListener('click',()=>{if(confirm('Erase all planner data on this device?')){data=structuredClone(blank);closeSheet();save()}})}
function settingsSection(title,rows){return `<section class="settings-section"><div class="settings-label">${title}</div><div class="settings-group">${rows}</div></section>`}function selectRow(label,name,options,value){return `<label class="settings-row"><b>${label}</b><select name="${name}">${options.map(x=>`<option value="${x[0]}" ${String(value)===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label>`}function toggleRow(label,name,on){return `<label class="settings-row"><b>${label}</b><span class="ios-toggle"><input type="checkbox" name="${name}" ${on?'checked':''}><i></i></span></label>`}function timeRow(label,name,value){return `<label class="settings-row"><b>${label}</b><input type="time" name="${name}" value="${value}"></label>`}function numberRow(label,name,value,min,max){return `<label class="settings-row"><b>${label}</b><input type="number" name="${name}" value="${value}" min="${min}" max="${max}"></label>`}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{current=b.dataset.view;render();view.focus()});$('#quickAdd').onclick=openQuick;$('#settingsBtn').onclick=openSettings;$('#themeBtn').onclick=()=>{data.theme=data.theme==='light'?'dark':data.theme==='dark'?'auto':'light';save();toast(`Theme: ${data.theme}`)};if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');render();
